pub(crate) fn locale_patterns(lang: &str) -> (&'static str, &'static str) {
    match lang {
        "ar" => ("{0} ({1})", "{0}، {1}"),
        "de" => ("{0} ({1})", "{0}, {1}"),
        "en" => ("{0} ({1})", "{0}, {1}"),
        "es" => ("{0} ({1})", "{0}, {1}"),
        "fr" => ("{0} ({1})", "{0}, {1}"),
        "gv" => ("{0} ({1})", "{0}, {1}"),
        "hi" => ("{0} ({1})", "{0}, {1}"),
        "it" => ("{0} ({1})", "{0}, {1}"),
        "ja" => ("{0} ({1})", "{0}、{1}"),
        "ko" => ("{0}({1})", "{0}, {1}"),
        "ln" => ("{0} ({1})", "{0}, {1}"),
        "nl" => ("{0} ({1})", "{0}, {1}"),
        "pl" => ("{0} ({1})", "{0}, {1}"),
        "pt" => ("{0} ({1})", "{0}, {1}"),
        "ru" => ("{0} ({1})", "{0}, {1}"),
        "si" => ("{0} ({1})", "{0}, {1}"),
        "sl" => ("{0} ({1})", "{0}, {1}"),
        "sr" => ("{0} ({1})", "{0}, {1}"),
        "sv" => ("{0} ({1})", "{0}, {1}"),
        "th" => ("{0} ({1})", "{0}, {1}"),
        "zh" => ("{0}（{1}）", "{0}，{1}"),
        _ => ("{0} ({1})", "{0}, {1}"),
    }
}
